const runs:any[]=[];

const faults=[{"path":"src/infrastructure/database/event-log.ts","kind":"omit-raw-admission","from":"createSourceOperationAdmission(activeLogPath).run(","to":"((operation:()=>Promise<void>,_parent:unknown)=>operation())(","pattern":"raw append|all adopted"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-replay-admission","from":"createSourceOperationAdmission(logPath, sourceDirectory).run(","to":"((operation:()=>Promise<any>,_parent:unknown)=>operation())(","pattern":"replay and recovery|all adopted"},{"path":"src/infrastructure/database/projection-recovery.ts","kind":"omit-recovery-admission","from":"createSourceOperationAdmission(logPath, sourceDirectory).run(","to":"((operation:(lease:undefined)=>Promise<any>,_parent:unknown)=>operation(undefined))(","pattern":"replay and recovery|all adopted"},{"path":"src/infrastructure/database/projection-recovery.ts","kind":"omit-writer-admission","from":"createSourceOperationAdmission(logPath).run(","to":"((operation:(lease:undefined)=>Promise<any>,_parent:unknown)=>operation(undefined))(","pattern":"projected writes|all adopted"},{"path":"src/infrastructure/database/source-operation-admission.ts","kind":"ignore-explicit-directory","from":"eventsDir ?? getEventsDir()","to":"getEventsDir()","pattern":"replay and recovery"},{"path":"src/presentation/cli/commands/dream.ts","kind":"lose-dream-parent","from":"prepareDreamCommand(options, deps, lease)","to":"prepareDreamCommand(options, deps)","pattern":"first read"},{"path":"src/presentation/cli/commands/governance.ts","kind":"lose-governance-parent","from":"prepareGovernanceCommand(options, deps, lease)","to":"prepareGovernanceCommand(options, deps)","pattern":"governance writes source-backed"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"hide-component-errors","from":"`Operation scope and child work failed: ${failures.map(unknownErrorMessage).join(\"; \")}`","to":"\"Operation scope and child work failed\"","pattern":"outer and detached|retained event after failed replay"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
